.app {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  border-radius: var(--appsmith-theme-borderRadius);
  box-shadow: var(--appsmith-theme-boxShadow);
  padding: 12px;
  box-sizing: border-box;
  font-family: system-ui;
}
.ag-theme-alpine .ag-header { background: #fff !important; color: #222 !important; }
.ag-theme-alpine .ag-row-selected { background: var(--appsmith-theme-primaryColor) !important; color: #fff !important; }
.ag-theme-alpine { border-radius: var(--appsmith-theme-borderRadius); box-shadow: var(--appsmith-theme-boxShadow); }

