function pretty(k){return k.charAt(0).toUpperCase()+k.slice(1).replace(/([A-Z])/g,' $1').trim();}
function columnsFor(rows, picked){
  const fields = (Array.isArray(picked) && picked.length>0)
    ? picked
    : (rows[0] ? Object.keys(rows[0]) : []);
  return fields.map(f => ({
    headerName: pretty(f),
    field: f,
    sortable: true,
    filter: true,
    resizable: true,
    valueFormatter: p => (p.value && typeof p.value === 'object') ? JSON.stringify(p.value) : p.value
  }));
}
function normalize(model){
  return Array.isArray(model && model.rows) ? model.rows : [];
}
let gridApi = null;
function render(model){
  const rows = normalize(model);
  const cols = columnsFor(rows, model && model.columns);
  const div = document.getElementById('aggrid-root');
  if(!div) return;
  div.innerHTML = '';
  const opts = {
    columnDefs: cols,
    rowData: rows,
    defaultColDef: { sortable:true, filter:true, resizable:true, minWidth:120 },
    animateRows: true,
    pagination: true,
    paginationPageSize: 100,
    onGridReady: (e) => { gridApi = e.api; }
  };
  new agGrid.Grid(div, opts);
}
appsmith.onReady(() => {
  render(appsmith.model);
  appsmith.onModelChange(render);
});

